function readJSONStore(k,fallback){try{let v=JSON.parse(localStorage.getItem(k)||'null');return v&&typeof v==='object'?v:fallback}catch{return fallback}}
function taskStats(){return readJSONStore('pflTaskStats',{})}
function bumpStat(k,n=1){let s=taskStats();s[k]=Math.max(0,(Number(s[k])||0)+n);localStorage.pflTaskStats=JSON.stringify(s);scheduleTaskRender()}
function setStat(k,v=1){let s=taskStats();s[k]=v;localStorage.pflTaskStats=JSON.stringify(s);scheduleTaskRender()}
function setSeen(k,v){let s=taskStats(),a=new Set(Array.isArray(s[k])?s[k]:[]);a.add(v);s[k]=[...a].slice(0,100);localStorage.pflTaskStats=JSON.stringify(s);scheduleTaskRender()}
function getControlSettings(){let saved=readJSONStore('pflControls',{}),base=CONTROL_PRESETS[saved.preset]||CONTROL_PRESETS.explorer;return{preset:saved.preset||'explorer',sens:Number(saved.sens)||base.sens,invert:saved.invert??base.invert,reduced:saved.reduced??base.reduced,haptics:saved.haptics??base.haptics}}
function saveControlSettings(v){localStorage.pflControls=JSON.stringify(v);applyControlSettings();renderControls()}
function applyControlSettings(){let s=getControlSettings();document.body.classList.toggle('reduceMotion',!!s.reduced);document.body.classList.toggle('largeControls',s.preset==='accessible')}
function haptic(ms=14){let s=getControlSettings();if(s.haptics&&navigator.vibrate)navigator.vibrate(Math.max(5,Math.min(80,ms)))}
function visitedCount(){try{return new Set(JSON.parse(localStorage.pflVisited||'[]')).size}catch{return 0}}
function cameraCount(){let s=taskStats();return new Set(Array.isArray(s.views)?s.views:[]).size}
