function planetTick(ts){if(!SPHERE.last)SPHERE.last=ts;let dt=Math.min(33,ts-SPHERE.last);SPHERE.last=ts;let auto=$('autoRotate')?.checked||st.view==='action';if(auto){SPHERE.spin+=dt*.00026;SPHERE.cloudSpin+=dt*.00034}renderPlanetNow();if(auto||drag||document.querySelector('dialog[open]')===null&&st.view==='action')SPHERE.loop=requestAnimationFrame(planetTick);else SPHERE.loop=0}
function schedulePlanetRender(forceLoop=false){if(forceLoop||$('autoRotate')?.checked||st.view==='action'){if(!SPHERE.loop)SPHERE.loop=requestAnimationFrame(planetTick)}else if(!SPHERE.frame){SPHERE.frame=requestAnimationFrame(()=>{SPHERE.frame=0;renderPlanetNow()})}}
window.addEventListener('resize',()=>{ensureCanvasSize();schedulePlanetRender()});

function renderBody(){let p=P[st.body],tx=TEX[p[0]],rel=(kmDiameter(p[0])/EARTH_DIAMETER).toFixed(2),scaleNote=(bodyScale(p[0])/bodyScale('Earth')).toFixed(2);$('title').textContent=p[0];$('summary').textContent=p[7];$('planet').className='planet '+p[1];$('rings').style.display=p[0]=='Saturn'?'block':'none';$('textureLayer').style.backgroundImage='none';$('textureLayer').style.opacity='0';$('facts').innerHTML=`<div class=fact><b>Class</b>${p[2]}</div><div class=fact><b>Diameter</b>${p[8]}</div><div class=fact><b>Gravity</b>${p[3]}</div><div class=fact><b>Day</b>${p[9]}</div><div class=fact><b>Year</b>${p[5]}</div><div class=fact><b>Atmosphere</b>${p[10]}</div><div class=fact><b>Temperature</b>${p[4]}</div><div class=fact><b>Moons</b>${p[11]}</div><div class=fact><b>Relative size</b>${rel}× Earth</div><div class=fact><b>Display scale</b>${scaleNote}× Earth view</div><div class=fact><b>Visual layer</b>${tx?tx.label:'PROCEDURAL FALLBACK'}</div><div class=fact><b>Source</b>${tx?tx.source:'Local procedural renderer'}</div><div class=sourceInline>${sourceButton('bodies',p[1],'World sources')}${tx?sourceButton('textures',p[0],'Texture provenance'):''}</div>`;syncPlanetScale();schedulePlanetRender(true);trackVisit()}
function meters(){$('meters').innerHTML=keys.map(([k,n])=>`<label>${n}<span>${Math.round(st[k])}%</span><meter min=0 max=100 value=${st[k]}></meter></label>`).join('');let risk=(100-st.cr)+(100-st.atm)+st.rot+st.rad+st.deb;$('caption').textContent=risk>260?'Catastrophic compound state · explore recovery branches.':risk>150?'Severe planetary stress · multiple systems affected.':'Stable/perturbed system · choose another event.'}
function deck(){$('deck').innerHTML='';S[st.kind].forEach(s=>{let b=document.createElement('button');b.className='scenario';b.innerHTML=`<b>${s[0]} ${s[1]}</b><small>${s[3]}</small><em>${s[2]}</em>`;b.onclick=()=>apply(s);$('deck').appendChild(b)})}
function chain(){$('chain').innerHTML=st.hist.length?st.hist.slice().reverse().map(x=>`<div class="node ${x.k=='hazard'?'h':x.k=='recovery'?'r':''}"><b>${esc(x.n)}</b><small>${esc(x.t)}${x.by?' · '+esc(x.by):''}</small></div>`).join(''):'<div class=node><b>Start</b><small>Stable selected world</small></div>'}
function snap(){return JSON.parse(JSON.stringify(st))}
function narrate(text){if(st.view!=='action'||!('speechSynthesis'in window))return;speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.rate=.95;u.pitch=.95;speechSynthesis.speak(u)}
function actionFx(kind,text){let fx=$('eventFx');fx.className='eventFx active '+(kind=='recovery'?'recovery':'hazard');$('stage').classList.add('direct-hit');setTimeout(()=>{$('stage').classList.remove('direct-hit');fx.className='eventFx'},1450);narrate(text)}
function apply(s){if(!localStorage.pflAlias){$('acct').showModal();$('acctMsg').textContent='Create a public alias before running scenarios on this installation.';return false}st.undo=snap();Object.entries(s[4]).forEach(([k,v])=>st[k]=cl((st[k]??0)+v));let by='';if(st.mode==='multiplayer'){let party=getParty();if(party.players.length){by=party.players[party.turn%party.players.length];party.turn=(party.turn+1)%party.players.length;localStorage.pflParty=JSON.stringify(party);renderMode()}}if(st.mode==='versus')scoreVersus(st.kind,s);st.hist.push({n:s[1],t:s[2],k:st.kind,by});st.eventsRun=(st.eventsRun||0)+1;bumpStat(st.kind==='hazard'?'hazardEvents':st.kind==='recovery'?'recoveryEvents':'seasonalEvents');if(st.mode==='multiplayer')bumpStat('multiplayerTurns');if(st.mode==='director')bumpStat('directorEvents');if(/asteroid|comet/i.test(s[1]))setStat('impactModeled',1);if(/deflection/i.test(s[1]))setStat('deflectionApplied',1);$('truth').textContent=s[2];$('truth').className='badge '+(st.kind=='recovery'?'good':st.kind=='hazard'?'warn':'');meters();chain();tone(st.kind=='hazard'?90:220);actionFx(st.kind,s[1]+'. '+s[3]);toast((by?by+': ':'')+s[1]);if(st.eventsRun%3===0)setTimeout(()=>offerBonus(),650);return true}
function reset(){st={...st,mag:100,atm:100,cr:100,rot:10,rad:10,deb:5,hist:[],undo:null};meters();chain();$('truth').textContent='CURATED';$('truth').className='badge good'}
let audioCtx=null;function tone(f){try{let AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioCtx=audioCtx||new AC();if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});let a=audioCtx,o=a.createOscillator(),g=a.createGain();o.frequency.value=f;g.gain.value=.05;o.connect(g).connect(a.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.45);o.stop(a.currentTime+.5)}catch{}}
function forces(){$('forces').innerHTML=F.map(x=>`<label>${x[1]}<span id=v-${x[0]}>${x[2]}%</span><input id=f-${x[0]} type=range min=0 max=100 value=${x[2]}><small class=muted>${x[3]}</small></label>`).join('');F.forEach(x=>$('f-'+x[0]).oninput=e=>$('v-'+x[0]).textContent=e.target.value+'%')}
function applyF(){let v={};F.forEach(x=>v[x[0]]=+$('f-'+x[0]).value);st.undo=snap();st.rot=cl(v.rotation);st.cr=cl(110-(v.tidal*.28+v.rotation*.28+v.impact*.48));st.atm=cl(105-(v.radiation*.22+v.impact*.18+v.solarwind*.12)+v.drag*.08);st.mag=cl(103-v.radiation*.05-v.impact*.05-v.solarwind*.09);st.rad=cl(v.radiation*.72+v.solarwind*.32);st.deb=cl(v.debris+v.impact*.18);st.hist.push({n:'Custom force model',t:'SANDBOX MODEL',k:'seasonal'});meters();chain();if(st.view==='action')actionFx('hazard','Custom force model applied. Review the changed telemetry.');bumpStat('forceModels');toast('Force model applied')}
async function fetchTimed(url,opts={}){let ctrl=new AbortController(),tm=setTimeout(()=>ctrl.abort(),9000);try{return await fetch(url,{...opts,signal:ctrl.signal})}finally{clearTimeout(tm)}}
const DISCLOSURE={facilities:null,entities:null,loaded:false,context:null,scope:'all'};
async function loadDisclosure(){if(DISCLOSURE.loaded)return DISCLOSURE;try{let [fr,er]=await Promise.all([fetchTimed('./data/launch_sites.json'),fetchTimed('./data/entity_compliance.json')]);if(!fr.ok||!er.ok)throw new Error('disclosure policy unavailable');DISCLOSURE.facilities=await fr.json();DISCLOSURE.entities=await er.json();DISCLOSURE.loaded=true;return DISCLOSURE}catch(e){DISCLOSURE.loaded=true;DISCLOSURE.facilities={sites:[]};DISCLOSURE.entities={entities:[]};return DISCLOSURE}}
function complianceButton(id,label='Disclosure policy',scope='facility'){return `<button class="complianceLink" data-compliance-id="${esc(id)}" data-compliance-scope="${esc(scope)}">${esc(label)}</button>`}
function renderCompliance(){let q=($('complianceSearch')?.value||'').toLowerCase().trim(),f=$('complianceFilter')?.value||'all',scope=$('complianceScope')?.value||DISCLOSURE.scope||'all',sites=DISCLOSURE.facilities?.sites||[],entities=DISCLOSURE.entities?.entities||[];if(DISCLOSURE.context){if(DISCLOSURE.context.scope==='facility')sites=sites.filter(x=>x.id===DISCLOSURE.context.id),entities=[];else entities=entities.filter(x=>x.id===DISCLOSURE.context.id),sites=[]}else{if(scope==='facilities')entities=[];if(scope==='entities')sites=[]}sites=sites.filter(x=>(f==='all'||x.securityClass===f)&&(!q||[x.name,x.operator,x.location,x.jurisdiction,x.securityClass,x.publicAccess].join(' ').toLowerCase().includes(q)));entities=entities.filter(x=>!q||[x.name,x.kind,x.usePolicy,x.securityPolicy].join(' ').toLowerCase().includes(q));let cards=[];cards.push(...sites.map(x=>`<article class="sourceCard"><div class="sourceHead"><div><b>${esc(x.name)}</b><small>${esc(x.operator)} · ${esc(x.location)}</small></div><span class="evidence">${esc(x.securityClass)}</span></div><p><b>Public access:</b> ${esc(x.publicAccess)}</p><p><b>Map policy:</b> ${esc(x.mapPolicy)}</p><p><b>Photography/media:</b> ${esc(x.photographyPolicy)}</p><p><b>Allowed:</b> ${(x.allowedPublicInfo||[]).map(v=>esc(v)).join(' · ')}</p><p class="bad"><b>Excluded:</b> ${(x.excludedInfoClasses||[]).map(v=>esc(v)).join(' · ')}</p><div class="row"><a href="${esc(x.officialVisitorUrl)}" target="_blank" rel="noopener noreferrer">Official visitor/access guidance ↗</a><a href="${esc(x.officialPolicyUrl)}" target="_blank" rel="noopener noreferrer">Official policy ↗</a></div><div class=sourceInline>${sourceButton('facility_compliance',x.id,'Policy sources')}</div></article>`));cards.push(...entities.map(x=>`<article class="sourceCard"><div class="sourceHead"><div><b>${esc(x.name)}</b><small>${esc(x.kind||'Official entity/provider')}</small></div><span class="evidence">ENTITY POLICY</span></div><p><b>Use/media policy:</b> ${esc(x.usePolicy)}</p><p><b>Security/disclosure policy:</b> ${esc(x.securityPolicy)}</p><div class=sourceInline>${sourceButton('entity_compliance',x.id,'Policy sources')}</div></article>`));$('complianceList').innerHTML=cards.length?cards.join(''):'<div class="callout muted">No matching disclosure/compliance record.</div>'}
async function openCompliance(id=null,scope='facility'){await loadDisclosure();DISCLOSURE.context=id?{id,scope}:null;DISCLOSURE.scope=id?scope:'all';$('complianceSearch').value='';$('complianceFilter').value='all';if($('complianceScope'))$('complianceScope').value=id?(scope==='entity'?'entities':'facilities'):'all';renderCompliance();$('complianceDlg').showModal()}

const PROV={sources:[],index:new Map(),map:{},loaded:false,context:null};
const SOURCE_ALIASES={clipper:'europa_clipper'};
async function loadProvenance(){if(PROV.loaded)return PROV;try{let [sr,mr]=await Promise.all([fetchTimed('./data/source_registry.json'),fetchTimed('./data/content_source_map.json')]);if(!sr.ok||!mr.ok)throw new Error('source registry unavailable');let [s,m]=await Promise.all([sr.json(),mr.json()]);PROV.sources=Array.isArray(s.sources)?s.sources:[];PROV.index=new Map(PROV.sources.map(x=>[x.id,x]));PROV.map=m.namespaces||{};PROV.loaded=true;renderSourceEvidenceOptions();return PROV}catch(e){PROV.loaded=true;PROV.sources=[];PROV.index=new Map();PROV.map={};return PROV}}
function sourceIdsFor(ns,id){let key=SOURCE_ALIASES[id]||id,bucket=PROV.map?.[ns]||{};return bucket[key]||bucket[id]||bucket['*']||[]}
function sourceButton(ns,id,label='Sources'){return `<button class="sourceBtn" data-source-ns="${esc(ns)}" data-source-id="${esc(id)}">${esc(label)}</button>`}
function renderSourceEvidenceOptions(){let sel=$('sourceEvidence');if(!sel)return;let vals=[...new Set(PROV.sources.map(s=>s.evidence).filter(Boolean))].sort();sel.innerHTML='<option value="all">All evidence classes</option>'+vals.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}
function renderSources(){let q=($('sourceSearch')?.value||'').trim().toLowerCase(),ev=$('sourceEvidence')?.value||'all',ids=PROV.context?.ids||null,list=PROV.sources.filter(s=>(!ids||ids.includes(s.id))&&(ev==='all'||s.evidence===ev)&&(!q||[s.title,s.organization,s.type,s.evidence,s.notes,(s.covers||[]).join(' ')].join(' ').toLowerCase().includes(q)));$('sourceList').innerHTML=list.length?list.map(s=>`<article class="sourceCard"><div class="sourceHead"><div><b>${esc(s.title)}</b><small>${esc(s.organization)} · ${esc(s.type||'source')}</small></div><span class="evidence">${esc(s.evidence||'SOURCE')}</span></div><small>Retrieved ${esc(s.retrievedAt||'not recorded')}${s.notes?' · '+esc(s.notes):''}</small><div class="sourceCoverage">${(s.covers||[]).slice(0,7).map(x=>`<i>${esc(x)}</i>`).join('')}</div><p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open publisher/source ↗</a></p>${s.licenseNote?`<small>${esc(s.licenseNote)}</small>`:''}</article>`).join(''):'<div class="callout muted">No source records match this filter.</div>'}
