async function live(){let h=$('live');h.innerHTML='<p class=muted>Loading public feeds…</p>';let a=[];try{let r=await fetchTimed('https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json',{cache:'no-store'}),j=await r.json(),q=j[j.length-1];a.push(`<div class=live><b>NOAA planetary K-index</b><h2>${esc(q?.[1]??'?')}</h2><small>LIVE · ${esc(q?.[0]??'')}</small></div>`)}catch{a.push('<div class=live><b>NOAA SWPC</b><small>Feed unavailable in this browser; open NOAA from Resources.</small></div>')}try{let d=new Date(),e=new Date(Date.now()+86400000),iso=x=>x.toISOString().slice(0,10),r=await fetchTimed(`https://ssd-api.jpl.nasa.gov/cad.api?date-min=${iso(d)}&date-max=${iso(e)}&dist-max=0.05`,{cache:'no-store'}),j=await r.json();a.push(`<div class=live><b>JPL close approaches</b><h2>${j.count??j.data?.length??'?'}</h2><small>LIVE · next 24 h / 0.05 AU query</small></div>`)}catch{a.push('<div class=live><b>JPL CNEOS</b><small>Feed unavailable in this browser; open CNEOS from Resources.</small></div>')}h.innerHTML=a.join('');bumpStat('liveChecks')}
