function renderCycles(){let tabs=$('cycleTabs'),grid=$('cycleGrid');tabs.innerHTML=cycleCats().map(c=>`<button data-cyclecat="${c}" class="${st.cycleCat===c?'active':''}">${c}</button>`).join('');let list=CYCLES.filter(c=>c.cat===st.cycleCat);grid.innerHTML=list.map(c=>`<button class="cycleCard" data-cycle="${c.id}"><b>${c.name}</b><div class=cyclePeriod>${c.period}</div><small>${c.mechanism}</small><em>${c.evidence}</em><div class=cycleScale><i style="width:${c.scale}%"></i></div></button>`).join('')}
