function renderOps(tab=st.opsTab){st.opsTab=tab;document.querySelectorAll('#opsTabs button').forEach(b=>b.classList.toggle('active',b.dataset.op===tab));let data=tab==='missions'?MISSIONS:tab==='craft'?CRAFT:SITES;$('opsGrid').innerHTML=data.map(x=>`<div class=opsCard><span class=craftIcon>${x.icon||'📍'}</span><b>${x.name}</b><small>${tab==='missions'?x.goal:tab==='craft'?x.mission:x.best}</small><div class=missionMeta><span>${tab==='missions'?x.agency:tab==='craft'?x.type:x.place}</span><span>${tab==='missions'?x.target:tab==='craft'?x.operator:x.agency}</span></div><button data-brief="${tab}:${x.id}">Brief</button></div>`).join('')}
