function getCrew(){try{let a=JSON.parse(localStorage.pflCrew||'[]');if(!Array.isArray(a))return[];return a.slice(0,6).filter(x=>x&&typeof x==='object').map(x=>({id:String(x.id||'').slice(0,80),name:String(x.name||'Crew').slice(0,40),role:String(x.role||'Specialist').slice(0,80),track:String(x.track||'field').slice(0,40),specialties:Array.isArray(x.specialties)?x.specialties.slice(0,6).map(v=>String(v).slice(0,80)):[],stats:Object.fromEntries(['science','engineering','medical','piloting','leadership','field','robotics'].map(k=>[k,cl(Number(x.stats?.[k])||0)]))}))}catch{return[]}}
