function renderCrew(){let filter=$('crewFilter')?.value||'all',picked=getCrew(),pickedIds=new Set(picked.map(x=>x.id)),arr=CHARACTERS.filter(c=>filter==='all'||c.track===filter);$('crewGrid').innerHTML=arr.map(c=>`<button class="crewCard ${pickedIds.has(c.id)?'selected':''}" data-crew="${c.id}"><b>${esc(c.name)}</b><small>${esc(c.role)} · ${esc(c.specialties.join(' · '))}</small><div class=statline><span>SCI ${c.stats.science}</span><span>ENG ${c.stats.engineering}</span><span>MED ${c.stats.medical}</span><span>PIL ${c.stats.piloting}</span><span>LDR ${c.stats.leadership}</span><span>EVA ${c.stats.field}</span><span>ROB ${c.stats.robotics}</span></div></button>`).join('');$('crewManifest').innerHTML=picked.length?picked.map(c=>`<div class=manifestRow><span><b>${esc(c.name)}</b><small class=muted>${esc(c.role)}</small></span><button data-removecrew="${esc(c.id)}">Remove</button></div>`).join(''):'<p class=muted>No crew selected yet.</p>';let roles=['science','engineering','medical','piloting','leadership','field','robotics'],coverage=roles.filter(k=>picked.some(c=>(c.stats?.[k]||0)>=82)).length;$('crewBalance').innerHTML=picked.length?`<b>${picked.length}/6 crew · role coverage ${coverage}/7</b><p>${coverage>=5?'Strong interdisciplinary manifest.':'Add complementary specialists to improve resilience.'}</p>`:'Select up to six crew members. Balanced teams unlock better mission outcomes.'}
