function renderExpansion(tab=expTab){expTab=tab;document.querySelectorAll('#expTabs button').forEach(b=>b.classList.toggle('active',b.dataset.exp===tab));let data,title;if(tab==='missioncontrol'){title='Mission Control Career';data=MISSION_PHASES.map((x,i)=>({id:x.id,name:(i+1)+'. '+x.name,small:x.objective,tag:'CAMPAIGN PHASE'}))}else if(tab==='rescue'){title='Search & Rescue';data=RESCUES.map(x=>({id:x.id,name:x.name,small:x.brief,tag:x.classification}))}else if(tab==='colony'){title='Colonization & Settlement';data=COLONY.destinations.map(x=>({id:x.id,name:x.name,small:x.strengths.join(' · '),tag:'SIMULATION'}))}else if(tab==='inner'){title='Inner Worlds';data=INNER.map(x=>({id:x.id,name:x.name,small:x.target+' · '+x.status,tag:x.class}))}else if(tab==='frontier'){title='Sci-Fi Frontier Tech';data=FRONTIER.map(x=>({id:x.id,name:x.name,small:x.basis,tag:x.class}))}else{title='Scenario Creator Studio';data=[{id:'creator',name:'New Scenario Pack',small:'Define a title, evidence class, objective, narrative and telemetry deltas; export as JSON.',tag:'CREATOR'}]};$('expTitle').textContent=title;$('expGrid').innerHTML=data.map(x=>`<button class=expCard data-expitem="${x.id}"><b>${x.name}</b><small>${x.small}</small><span class=frontierTag>${x.tag}</span></button>`).join('');if(tab==='missioncontrol')renderMissionControl();else if(tab==='rescue')renderRescueConsole();else if(tab==='colony')renderColony();else if(tab==='inner')$('expConsole').innerHTML='<div class=callout>Select a mission card to inspect current/historical/future inner-Solar-System operations.</div>';else if(tab==='frontier')$('expConsole').innerHTML='<div class=callout><b>Evidence firewall</b><p>Green = known physics; amber = research/speculative theory; red = fictional extrapolation. Portals and warp travel are not presented as demonstrated technology.</p></div>';else renderCreator()}
function expItem(id){if(expTab==='missioncontrol'){missionPhase=Math.max(0,MISSION_PHASES.findIndex(x=>x.id===id));renderMissionControl();return}if(expTab==='rescue'){let x=RESCUES.find(v=>v.id===id);if(x)runRescue(x);return}if(expTab==='colony'){initColony(id);renderColony();return}if(expTab==='inner'){let x=INNER.find(v=>v.id===id);if(!x)return;setSeen('innerViewed',id);$('expConsole').innerHTML=`<div class=callout><b>${x.name} · ${x.class}</b><p>${x.status}</p></div><p><b>Agency:</b> ${x.agency}</p><p><b>Target:</b> ${x.target}</p><p><b>Goal:</b> ${x.goal}</p><p><b>Teaches:</b> ${x.tech.join(' · ')}</p><div class=sourceInline>${sourceButton('inner_worlds',id,'Mission sources')}</div>`;return}if(expTab==='frontier'){let x=FRONTIER.find(v=>v.id===id);if(!x)return;setSeen('frontierViewed',id);setStat('frontierOpened',1);let cls=x.class.includes('KNOWN')||x.class.includes('OBSERVED')?'evidenceObserved':x.class.includes('FICTION')?'evidenceFiction':'evidenceSpec';$('expConsole').innerHTML=`<div class="callout ${cls}"><b>${x.name}</b><p>${x.class}</p></div><p><b>Physics basis:</b> ${x.basis}</p><p><b>Unresolved leap:</b> ${x.leap}</p><p><b>Gameplay:</b> ${x.gameplay}</p><div class=sourceInline>${sourceButton('frontier',id,'Physics/source record')}</div>`;return}}
