function saveMissionPlan(p){localStorage.pflMissionPlan=JSON.stringify(p);scheduleTaskRender()}
function renderMissionControl(){
  let crew=getCrew(),plan=getMissionPlan();
  let mission=MISSIONS.find(x=>x.id===plan.mission)||MISSIONS[0],craft=CRAFT.find(x=>x.id===plan.craft)||CRAFT[0],site=SITES.find(x=>x.id===plan.site)||SITES[0];
  $('expConsole').innerHTML=`<div class=missionFlow>${MISSION_PHASES.map((p,i)=>`<div class="phase ${i===missionPhase?'on':''}">${i+1}. ${p.name}</div>`).join('')}</div>
  <div class=callout><b>${MISSION_PHASES[missionPhase].name}</b><p>${MISSION_PHASES[missionPhase].objective}</p></div>
  <div class=systems><div class=sysMeter><b>Mission / target</b><select id=mcMission style="width:100%">${MISSIONS.map(x=>`<option value="${x.id}" ${x.id===mission.id?'selected':''}>${x.name} → ${x.target}</option>`).join('')}</select></div>
  <div class=sysMeter><b>Craft / vessel</b><select id=mcCraft style="width:100%">${CRAFT.map(x=>`<option value="${x.id}" ${x.id===craft.id?'selected':''}>${x.name} · ${x.type}</option>`).join('')}</select></div>
  <div class=sysMeter><b>Launch site</b><select id=mcSite style="width:100%">${SITES.map(x=>`<option value="${x.id}" ${x.id===site.id?'selected':''}>${x.name} · ${x.place}</option>`).join('')}</select></div>
  <div class=sysMeter><b>Crew</b><p class=muted>${crew.length?crew.map(x=>esc(x.name)).join(', '):'No crew selected — use Crew & Characters.'}</p></div></div>
  <div class=callout><b>Architecture summary</b><p>${site.name} → ${craft.name} → ${mission.target}</p><p>${mission.goal}</p><small>${site.lesson} · ${craft.lesson} · ${mission.lesson}</small></div>
  <div class=row style="margin-top:9px"><button id=missionPrev ${missionPhase===0?'disabled':''}>Previous</button><button id=missionNext class=pri>${missionPhase===MISSION_PHASES.length-1?'Complete review':'Advance phase'}</button></div>`;
  setTimeout(()=>{
    ['mcMission','mcCraft','mcSite'].forEach(id=>{let el=$(id);if(el)el.onchange=()=>{saveMissionPlan({mission:$('mcMission').value,craft:$('mcCraft').value,site:$('mcSite').value});renderMissionControl()}});
    let a=$('missionPrev'),b=$('missionNext');if(a)a.onclick=()=>{missionPhase=Math.max(0,missionPhase-1);localStorage.pflMissionPhase=String(missionPhase);renderMissionControl()};if(b)b.onclick=()=>{if(missionPhase<MISSION_PHASES.length-1){missionPhase++;localStorage.pflMissionPhase=String(missionPhase);renderMissionControl()}else{setStat('missionComplete',1);unlock('Mission Architect','Completed the Mission Control architecture review.');toast('Mission architecture reviewed')}};
  },0)
}
function renderRescueConsole(){$('expConsole').innerHTML=`<div class=callout><b>NASA SAR-inspired training</b><p>Real Earth rescue uses 406 MHz distress beacons and satellite relay. Off-world cases are clearly labeled training/speculative scenarios.</p></div><div class=row><span class=badge>Drills ${rescueRuns}</span><span class=badge>Score ${rescueScore}</span></div><p class=muted>Select a rescue scenario card to start a decision drill.</p>`}
function runRescue(x){
  let opts=[x.bestActions[0],'Ignore the distress signal until the next shift','Spend all reserves immediately without localization'];
  let correct=0;
  $('expConsole').innerHTML=`<div class=callout><b>${x.name} · ${x.classification}</b><p>${x.brief}</p></div><p><b>Signals:</b> ${x.signals.join(' · ')}</p><p><b>Objective:</b> ${x.objective}</p><div class=sourceInline>${sourceButton('rescue',x.id,'SAR sources')}</div><div class=actionGrid>${opts.map((o,i)=>`<button data-rescue-answer="${i}">${o}</button>`).join('')}</div><div id=rescueResult></div>`;
  setTimeout(()=>{
    $('expConsole').querySelectorAll('[data-rescue-answer]').forEach(b=>{
      b.onclick=()=>{
        let ok=+b.dataset.rescueAnswer===correct;
        rescueRuns++;
        rescueScore+=ok?100:20;setStat('rescueRuns',rescueRuns);setStat('rescueScore',rescueScore);
        $('rescueResult').innerHTML=`<div class="callout ${ok?'evidenceObserved':'evidenceSpec'}"><b>${ok?'Good response':'Suboptimal response'}</b><p>${ok?x.lesson:'Review localization, reserve margins and crew safety before committing assets.'}</p></div>`;
        if(ok)unlock('Rescue Coordinator','Completed a SAR drill with the preferred response.');
      };
    });
  },0);
}
