function renderColony(){let c=getColony();if(!c){initColony(COLONY.destinations[0].id);c=getColony()}let keys=[['power','Power'],['water','Water'],['oxygen','Oxygen'],['food','Food'],['shielding','Shielding'],['spares','Spares'],['morale','Morale'],['science','Science']];$('expConsole').innerHTML=`<div class=callout><b>${esc(c.name)} · Sol/Day ${Number(c.sol)||0}</b><p class=colonylvl>Settlement simulation informed by life-support, habitation and ISRU concepts; not a prediction of a real colony.</p></div><div class=systems>${keys.map(([k,n])=>`<div class=sysMeter><b>${n} <span style="float:right">${Math.round(c[k])}%</span></b><meter min=0 max=100 value=${c[k]}></meter></div>`).join('')}</div><div class=sourceInline>${sourceButton('colonization',c.id,'Settlement sources')}</div><div class=actionGrid>${COLONY.actions.map(a=>`<button data-colony-action="${a.id}"><b>${a.name}</b><small>${a.lesson}</small></button>`).join('')}</div>`;setTimeout(()=>{$('expConsole').querySelectorAll('[data-colony-action]').forEach(b=>b.onclick=()=>colonyAction(b.dataset.colonyAction))},0)}
function colonyAction(id){let c=getColony(),a=COLONY.actions.find(x=>x.id===id);if(!c||!a)return;Object.entries(a.delta).forEach(([k,v])=>c[k]=cl((c[k]||0)+v));c.sol++;c.power=cl(c.power-2);c.water=cl(c.water-1);c.food=cl(c.food-1);c.oxygen=cl(c.oxygen-1);localStorage.pflColony=JSON.stringify(c);let min=Math.min(c.power,c.water,c.oxygen,c.food,c.shielding,c.spares);if(min<18)toast('Settlement critical: restore life-support margin');else if(c.science>85&&c.morale>70)unlock('Settlement Steward','Sustained a productive high-morale settlement.');renderColony();scheduleTaskRender()}
