function miniQuestion(id){let q={solar:['A simplified solar snapshot shows many sunspots and frequent eruptions. Which phase best fits?',['Solar maximum','Solar minimum'],0],launch:['A spacecraft needs a near-polar Earth orbit. Which U.S. launch site is typically advantageous?',['Vandenberg','Kennedy eastward corridor'],0],orbit:['A weather satellite must appear fixed over one longitude. Which orbit?',['Geostationary','Low Earth orbit','Polar orbit'],0],eclipse:['A closely similar eclipse geometry repeats after approximately…',['18 years 11 days 8 hours','11 years','100,000 years'],0],deflect:['Why is early asteroid deflection generally advantageous?',['A small velocity change has more time to grow into a large miss distance','Asteroids become softer with time','Gravity stops acting far from Earth'],0],planet:['Which planet is famous for an axial tilt near 90°, making it appear to rotate on its side?',['Uranus','Mars','Mercury'],0]};return q[id]||q.planet}
