function getVersus(){try{let v=JSON.parse(localStorage.pflVersus||'null');if(!v||typeof v!=='object')return null;return{restoreName:String(v.restoreName||'Restorers').slice(0,40),disruptName:String(v.disruptName||'Disruptors').slice(0,40),restoreScore:Math.max(0,Number(v.restoreScore)||0),disruptScore:Math.max(0,Number(v.disruptScore)||0),round:Math.max(0,Number(v.round)||0),maxRounds:Math.max(4,Math.min(20,Number(v.maxRounds)||10)),active:v.active==='restore'?'restore':'disrupt'}}catch{return null}}
