function startVersus(){let maxRounds=Math.max(4,Math.min(20,+$('versusRounds').value||10)),v={restoreName:$('restoreName').value.trim().slice(0,40)||'Restorers',disruptName:$('disruptName').value.trim().slice(0,40)||'Disruptors',restoreScore:0,disruptScore:0,round:0,maxRounds,active:'disrupt'};localStorage.pflVersus=JSON.stringify(v);setStat('versusStarted',1);st.mode='versus';localStorage.pflMode='versus';st.kind='hazard';syncTabs();renderVersus();renderMode();$('versusDlg').close();toast('Versus match started')}
function scoreVersus(kind,s){let v=getVersus();if(!v)return;let deltas=Object.values(s[4]).map(Number),power=Math.max(5,Math.min(25,Math.round(deltas.reduce((a,x)=>a+Math.abs(x),0)/4)||8));let correct=(v.active==='disrupt'&&kind==='hazard')||(v.active==='restore'&&kind==='recovery');if(v.active==='disrupt')v.disruptScore+=correct?power:Math.round(power/4);else v.restoreScore+=correct?power:Math.round(power/4);v.round++;bumpStat('versusTurns');if(v.round>=v.maxRounds){let win=v.restoreScore===v.disruptScore?'Draw':v.restoreScore>v.disruptScore?v.restoreName:v.disruptName;$('dlgTitle').textContent='Versus result';$('dlgBody').innerHTML=`<div class=callout><b>${esc(win)}</b><p>Final score: ${esc(v.restoreName)} ${v.restoreScore} · ${esc(v.disruptName)} ${v.disruptScore}</p></div><p class=muted>Review the outcome chain and explain which physical mechanisms produced the largest changes.</p>`;$('dlg').showModal();setStat('versusCompleted',1);localStorage.removeItem('pflVersus')}else{v.active=v.active==='disrupt'?'restore':'disrupt';st.kind=v.active==='disrupt'?'hazard':'recovery';localStorage.pflVersus=JSON.stringify(v);syncTabs()}renderMode()}
