function runModeAction(){if(st.mode==='story')return playStory();if(st.mode==='sandbox'){document.getElementById('lab').scrollIntoView({behavior:'smooth'});return}if(st.mode==='academy')return showTour();if(st.mode==='defense'){st.kind='hazard';syncTabs();live();document.getElementById('scenarios').scrollIntoView({behavior:'smooth'});toast('Planetary Defense mission started');return}if(st.mode==='multiplayer')return openParty();if(st.mode==='versus'){renderVersus();$('versusDlg').showModal();return}if(st.mode==='director'){setView('action');$('autoRotate').checked=true;$('stage').classList.add('sky-auto');document.getElementById('scenarios').scrollIntoView({behavior:'smooth'});return}if(st.mode==='seasonal'){st.kind='seasonal';syncTabs();document.getElementById('scenarios').scrollIntoView({behavior:'smooth'});return}if(st.mode==='missioncontrol'){renderExpansion('missioncontrol');document.getElementById('civilizationSec').scrollIntoView({behavior:'smooth'});return}if(st.mode==='rescue'){renderExpansion('rescue');document.getElementById('civilizationSec').scrollIntoView({behavior:'smooth'});return}if(st.mode==='colonization'){renderExpansion('colony');document.getElementById('civilizationSec').scrollIntoView({behavior:'smooth'});return}if(st.mode==='innerworlds'){renderExpansion('inner');document.getElementById('civilizationSec').scrollIntoView({behavior:'smooth'});return}if(st.mode==='timemachine'){document.getElementById('cyclesSec').scrollIntoView({behavior:'smooth'});toast('Use Cycles Observatory to move from orbital minutes to geologic eons');return}if(st.mode==='frontier'){renderExpansion('frontier');document.getElementById('civilizationSec').scrollIntoView({behavior:'smooth'});return}if(st.mode==='creator'){renderExpansion('creator');document.getElementById('civilizationSec').scrollIntoView({behavior:'smooth'});return}document.getElementById('explore').scrollIntoView({behavior:'smooth'})}
function playStory(){if(st.story>=STORY.length){$('dlgTitle').textContent='Story complete';$('dlgBody').innerHTML='<div class=callout><b>A New Planetary Age</b><p>You completed the current campaign. Reset the campaign to explore different event combinations and endings.</p></div><button id=storyReset class=pri>Restart campaign</button>';$('dlg').showModal();setTimeout(()=>{let b=$('storyReset');if(b)b.onclick=()=>{st.story=0;localStorage.pflStory='0';$('dlg').close();renderMode()}},0);return}if(!localStorage.pflAlias){$('acct').showModal();$('acctMsg').textContent='Create a public alias before starting the story campaign.';return}let ch=STORY[st.story],bi=P.findIndex(x=>x[0]===ch.body);if(bi>=0){st.body=bi;$('body').value=bi;renderBody()}st.kind=ch.kind;syncTabs();setView('action');let sc=S[ch.kind].find(x=>x[1]===ch.scenario);$('dlgTitle').textContent=ch.title;$('dlgBody').innerHTML=`<div class=callout><b>${ch.text}</b></div><p class=muted>Action Director will frame and narrate the event. Evidence labels remain visible throughout the sequence.</p><button id=chapterGo class=pri>Play chapter</button>`;$('dlg').showModal();setTimeout(()=>{let b=$('chapterGo');if(b)b.onclick=()=>{if(sc&&apply(sc)){st.story++;localStorage.pflStory=String(st.story);$('dlg').close();renderMode()}}},0)}
