function setView(v){st.view=v;trackCamera(v);let stage=$('stage');stage.classList.remove('first','third','action');if(v==='first')stage.classList.add('first');if(v==='third')stage.classList.add('third');if(v==='action')stage.classList.add('action');document.querySelectorAll('#cameraBar button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));let hints={skybox:'Cinematic orbital skybox with true spherical rendering and scaled planet diameters.',free:'Drag the true spherical globe to rotate it. Pinch/scroll changes zoom in Free Explorer.',first:'Surface/horizon perspective using the same spherical globe at a closer scale.',third:'Third-person orbital perspective with proportional body scaling for context.',action:'Cinematic director recenters events on the correctly scaled spherical world and narrates outcomes.'};$('viewHint').textContent=hints[v];$('viewBadge').textContent=v.replace(/-/g,' ').toUpperCase();stage.classList.toggle('sky-auto',$('autoRotate').checked);if(v==='skybox'){zoom=.8;ry=18;rx=-8}else if(v==='third'){zoom=.96}else if(v==='action'){zoom=1.02}else if(v==='free'){zoom=1}else if(v==='first'){zoom=1.12};setRig();schedulePlanetRender(true)}
function showTour(){tourStep=0;renderTour();$('tour').showModal()}function renderTour(){let s=TOUR[tourStep];$('tourTitle').textContent=s[0];$('tourBody').innerHTML=`<p>${s[1]}</p>${tourStep===2?'<div class="callout">Try every camera mode after the tutorial. Free Explorer is the default learning view; Action Director is the cinematic story view.</div>':''}`;$('tourDots').innerHTML=TOUR.map((_,i)=>`<i class="${i===tourStep?'on':''}"></i>`).join('');$('tourPrev').disabled=tourStep===0;$('tourNext').textContent=tourStep===TOUR.length-1?'Start exploring':'Next'}
