const rig=$('planetRig'),pointers=new Map();let pinch=null;rig.style.touchAction='none';rig.addEventListener('pointerdown',e=>{if(st.view==='action')return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});try{rig.setPointerCapture(e.pointerId)}catch{}if(pointers.size===1)drag={x:e.clientX,y:e.clientY,ry,rx};if(pointers.size===2){let a=[...pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);pinch={d,zoom};drag=null}});rig.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});let s=getControlSettings();if(pointers.size===2&&pinch&&st.view==='free'){let a=[...pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);zoom=Math.max(.65,Math.min(1.75,pinch.zoom*(d/Math.max(20,pinch.d))));scheduleRig();return}if(!drag)return;ry=drag.ry+(e.clientX-drag.x)*.45*s.sens;let dy=(e.clientY-drag.y)*.35*s.sens*(s.invert?-1:1);rx=Math.max(-75,Math.min(75,drag.rx-dy));scheduleRig()});function endPointer(e){pointers.delete(e.pointerId);if(pointers.size<2)pinch=null;if(!pointers.size)drag=null;else{let a=[...pointers.values()][0];drag={x:a.x,y:a.y,ry,rx}}}rig.addEventListener('pointerup',endPointer);rig.addEventListener('pointercancel',endPointer);rig.addEventListener('wheel',e=>{if(st.view!=='free')return;e.preventDefault();zoom=Math.max(.65,Math.min(1.75,zoom+(e.deltaY<0?.08:-.08)*getControlSettings().sens));setRig()},{passive:false});

