let gpLoop=0,gpPrev=[];function pollGamepad(){let pads=navigator.getGamepads?navigator.getGamepads():[],g=[...pads].find(Boolean);if(!g){$('gamepadStatus').textContent='NO GAMEPAD';gpLoop=0;return}$('gamepadStatus').textContent=(g.id||'GAMEPAD').slice(0,24);let s=getControlSettings(),dead=.18,x=Math.abs(g.axes[0]||0)>dead?g.axes[0]:0,y=Math.abs(g.axes[1]||0)>dead?g.axes[1]:0;if(x||y){ry+=x*1.8*s.sens;rx=Math.max(-75,Math.min(75,rx+(s.invert?y:-y)*1.5*s.sens));scheduleRig()}if((g.buttons[7]?.value||0)>.1){zoom=Math.max(.65,Math.min(1.75,zoom+(g.buttons[7].value||0)*.012*s.sens));scheduleRig()}if((g.buttons[6]?.value||0)>.1){zoom=Math.max(.65,Math.min(1.75,zoom-(g.buttons[6].value||0)*.012*s.sens));scheduleRig()}let press=i=>!!g.buttons[i]?.pressed&&!gpPrev[i];if(press(0))runModeAction();if(press(4))setView(['skybox','free','first','third','action'][Math.max(0,['skybox','free','first','third','action'].indexOf(st.view)-1)]);if(press(5))setView(['skybox','free','first','third','action'][Math.min(4,['skybox','free','first','third','action'].indexOf(st.view)+1)]);if(press(9))$('modesBtn').click();gpPrev=g.buttons.map(b=>!!b.pressed);gpLoop=requestAnimationFrame(pollGamepad)}window.addEventListener('gamepadconnected',()=>{if(!gpLoop)gpLoop=requestAnimationFrame(pollGamepad);haptic(20)});window.addEventListener('gamepaddisconnected',()=>{$('gamepadStatus').textContent='NO GAMEPAD'});
